{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "semio:world:analytic-wire-picking:v1",
  "title": "Original Analytic Wire Picking",
  "type": "object",
  "required": [
    "schema",
    "instance",
    "handle",
    "revision",
    "camera",
    "mesh",
    "transfer",
    "picks",
    "edgeOnly",
    "expected"
  ],
  "additionalProperties": false,
  "properties": {
    "schema": {
      "const": "world.analytic-wire-picking.v1"
    },
    "instance": {
      "type": "string",
      "minLength": 1
    },
    "handle": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "revision": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "camera": {
      "type": "object"
    },
    "mesh": {
      "type": "object"
    },
    "transfer": {
      "type": "object"
    },
    "picks": {
      "type": "array",
      "minItems": 2,
      "maxItems": 2,
      "items": {
        "type": "object",
        "required": [
          "kind",
          "pointer",
          "group",
          "expected"
        ],
        "additionalProperties": false,
        "properties": {
          "kind": {
            "enum": [
              "vertex",
              "edge"
            ]
          },
          "pointer": {
            "type": "array",
            "minItems": 2,
            "maxItems": 2,
            "items": {
              "type": "number"
            }
          },
          "group": {
            "type": "integer",
            "minimum": 0
          },
          "expected": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "edgeOnly": {
      "type":"object", "required":["mesh","expected"], "additionalProperties":false,
      "properties": {
        "mesh":{"type":"object"},
        "expected": {
          "type":"object", "required":["renderVertices","topologyVertices","edges","boundsMin","boundsMax"], "additionalProperties":false,
          "properties": {
            "renderVertices":{"const":8}, "topologyVertices":{"const":0}, "edges":{"const":4},
            "boundsMin":{"type":"array","minItems":3,"maxItems":3,"items":{"type":"number"}},
            "boundsMax":{"type":"array","minItems":3,"maxItems":3,"items":{"type":"number"}}
          }
        }
      }
    },
    "expected": {
      "type": "object",
      "required": [
        "vertices",
        "edges",
        "indices",
        "perimeter"
      ],
      "additionalProperties": false,
      "properties": {
        "vertices": {
          "const": 4
        },
        "edges": {
          "const": 4
        },
        "indices": {
          "const": 0
        },
        "perimeter": {
          "const": 2
        }
      }
    }
  }
}

{
